//
//  AcknowledgementsView.swift
//  Cog (iOS)
//
//  The third-party credits, as the macOS Acknowledgements window has them,
//  less what only the macOS app ships. Acknowledgements.json beside this
//  file is generated by Scripts/build-acknowledgements.py from
//  Acknowledgements/components.json; edit that, not the JSON.
//

import SwiftUI

struct Acknowledgements: Decodable {
	let groups: [String]
	let licenses: [String: String]
	let components: [Component]

	struct Component: Decodable, Identifiable {
		let group: String
		let name: String
		let version: String?
		let url: String?
		let license: String?
		let holders: [String]?
		let note: String?
		let texts: [String]

		var id: String { name }
	}

	static let shared: Acknowledgements? = {
		guard let url = Bundle.main.url(forResource: "Acknowledgements", withExtension: "json"),
		      let data = try? Data(contentsOf: url) else { return nil }
		return try? JSONDecoder().decode(Acknowledgements.self, from: data)
	}()
}

struct AcknowledgementsView: View {
	private let acknowledgements = Acknowledgements.shared
	@State private var query = ""

	var body: some View {
		List {
			ForEach(acknowledgements?.groups ?? [], id: \.self) { group in
				let components = matching(in: group)
				if !components.isEmpty {
					Section(title(forGroup: group)) {
						ForEach(components) { component in
							NavigationLink {
								AcknowledgementDetail(component: component, licenses: acknowledgements?.licenses ?? [:])
							} label: {
								VStack(alignment: .leading, spacing: 2) {
									Text(verbatim: component.name)
									if let holders = component.holders, !holders.isEmpty {
										Text(verbatim: holders.joined(separator: ", "))
											.font(.caption)
											.foregroundStyle(.secondary)
											.lineLimit(1)
									}
								}
							}
						}
					}
				}
			}
		}
		.searchable(text: $query)
		.navigationTitle("Acknowledgements")
		.navigationBarTitleDisplayMode(.inline)
	}

	/// A group's components, those the search names, by name, license or
	/// holder.
	private func matching(in group: String) -> [Acknowledgements.Component] {
		let components = acknowledgements?.components.filter { $0.group == group } ?? []
		let query = query.trimmingCharacters(in: .whitespaces)
		guard !query.isEmpty else { return components }
		return components.filter { component in
			([component.name, component.license ?? ""] + (component.holders ?? []))
				.contains { $0.localizedCaseInsensitiveContains(query) }
		}
	}

	/// As the macOS window titles them.
	private func title(forGroup group: String) -> LocalizedStringKey {
		switch group {
		case "audio": "Audio Engine and DSP"
		case "codecs": "Codecs and Formats"
		case "chiptune": "Game Music and Trackers"
		case "midi": "MIDI and Synthesis"
		case "app": "Application Components"
		case "swift": "Swift Packages"
		case "contributors": "Other Contributions"
		default: LocalizedStringKey(group)
		}
	}
}

/// A component's holders, license and where it is from, then its license
/// texts in full.
private struct AcknowledgementDetail: View {
	let component: Acknowledgements.Component
	let licenses: [String: String]

	var body: some View {
		ScrollView {
			VStack(alignment: .leading, spacing: 10) {
				// Here rather than as the title, where a long name is cut.
				Text(verbatim: component.name)
					.font(.title2.bold())
				if let version = component.version {
					Text("Version \(version)")
						.foregroundStyle(.secondary)
				}
				if let holders = component.holders, !holders.isEmpty {
					Text(verbatim: holders.joined(separator: "\n"))
				}
				if let license = component.license {
					HStack(alignment: .firstTextBaseline, spacing: 4) {
						Text("License:")
							.foregroundStyle(.secondary)
						if license == "Not stated in source" {
							Text("Not stated in source")
						} else {
							Text(verbatim: license)
						}
					}
				}
				if let note = component.note {
					Text(verbatim: note)
						.font(.callout)
						.foregroundStyle(.secondary)
				}
				if let string = component.url, let url = URL(string: string) {
					Link(string, destination: url)
				}
				ForEach(component.texts, id: \.self) { key in
					if let text = licenses[key] {
						Text(verbatim: text)
							.font(.system(.caption, design: .monospaced))
							.frame(maxWidth: .infinity, alignment: .leading)
							.padding(10)
							.background(Color(.secondarySystemBackground), in: RoundedRectangle(cornerRadius: 8))
					}
				}
			}
			.textSelection(.enabled)
			.padding()
			.frame(maxWidth: .infinity, alignment: .leading)
		}
		.navigationBarTitleDisplayMode(.inline)
	}
}
